function qmapMenu(){qmodal('行囊',`<div class="qactions">${btn('行事簿',"qjournal()")}${btn('重玩本关',"qclose();qreset()")}${btn('第二关',"qclose();switchCh(1)")}${btn('第三关',"qclose();switchCh(2)")}${btn('返回画卷',"qclose()")}</div><p class="qmuted">地图参考《姑苏繁华图》重绘。情境、任务与四季时间为游戏化设计。</p>`)}
render();;function easyFresh(){return{step:0,sample:null,assigned:[-1,-1,-1],selected:null,collected:[],checked:[],fixed:false,event:null,notice:'',place:null,menu:false}}
let easy;try{easy=JSON.parse(localStorage.getItem((globalThis.KESI_STORAGE_PREFIX||'')+'kesi-easy-v1'))}catch{}if(!easy)easy=easyFresh();const easySave=()=>saveGameSoon((globalThis.KESI_STORAGE_PREFIX||'')+'kesi-easy-v1',()=>easy);const easyNames=['沈师傅','周师傅','陆家织工'];const easyPos=[[15,42],[36,39],[51,59],[65,38],[81,52],[85,80]];const easyGuide=[['先接下差单','点击发光的「织造署」。'],['确认织造要求','点击「纱缎庄」，看看画师的画稿。'],['把三包任务送给织工','点一包任务，再点一家织户。也可以拖过去。'],['分工完成，开始织造','点击「开始织造」，看看工坊里发生了什么。'],['一户织工遇到困难','选一种办法，帮助这批差货继续完成。'],['把成品收回来','点击织户旁的「收货」，收齐三包。'],['交货前，看一看织面','点击三块织面检查；发现问题时可以修整。'],['差货齐了，送上船','点击发光的「葑门差船」。'],['差货已经装船','你把需求、织工和交付连接了起来。']];function easyAllowed(i){return easy.step===0?i===0:easy.step===1?i===1:easy.step===2?i>=2&&i<=4:easy.step===5?i>=2&&i<=4&&easy.assigned.some((w,n)=>w===i-2&&!easy.collected.includes(n)):easy.step===7?i===5:false}
function easyRender(){if(s.ch!==0)return;document.body.classList.add('qing','easy-mode');$('intro').close();const[title,hint]=easyGuide[easy.step];let tips=easy.notice||hint;$('qingApp').innerHTML=`<div class="easy-scene season-${Math.min(3,Math.floor(easy.step/2))}"><div class="easy-brand">缂丝经纬<span>第一关 · 差货入京</span></div><div class="easy-menu">${btn('全屏',"full()")}${btn('⋯',"easy.menu=!easy.menu;easyRender()")}</div><div class="easy-season">${['春 · 接洽','夏 · 承织','秋 · 收货','冬 · 交割'][Math.min(3,Math.floor(easy.step/2))]}</div><div class="easy-guide" aria-live="polite"><small>${easy.step===8?'完成':'第 '+([0,0,1,1,2,3,3,4,4][easy.step]+1)+' / 5 步'}</small><h2>${title}</h2><p>${tips}</p></div>${['苏州织造署','纱缎庄','沈家织户','周家织户','陆家织户','葑门差船'].map((n,i)=>`<button class="easy-place ${easyAllowed(i)?'glow':''}"style="left:${easyPos[i][0]}%;top:${easyPos[i][1]}%"data-easy-worker="${i>=2&&i<=4?i-2:-1}"onclick="easyVisit(${i})">${easyAllowed(i)?'<span class="easy-pointer">▼</span>':''}${n}${i>=2&&i<=4&&easy.step>=2?`<small>${easy.assigned.filter(w=>w===i-2).length?'已接 '+easy.assigned.filter(w=>w===i-2).length+' 包':easy.step===2?'可接任务':'—'}</small>`:''}</button>`).join('')}${easy.step===5?[0,1,2].map(w=>{let num=easy.assigned.filter((a,i)=>a===w&&!easy.collected.includes(i)).length;return num?`<button class="easy-collect glow"style="left:${easyPos[w+2][0]}%;top:${easyPos[w+2][1]+10}%"onclick="easyCollect(${w})">▣ 收货 × ${num}</button>`:''}).join(''):''}<div class="easy-work" id="easyWork">${easyContent()}</div><div class="easy-path">${['接单','分工','应变','收验','交付'].map((t,i)=>`<span class="${i<=[0,0,1,1,2,3,3,4,4][easy.step]?'done':''}">${i<[0,0,1,1,2,3,3,4,4][easy.step]?'✓ ':''}${t}</span>`).join('<i>—</i>')}</div>${easy.menu?`<div class="easy-menupop">${btn('重新开始',"easyReset()")}${btn('进入第二关',"switchCh(1)")}${btn('进入第三关',"switchCh(2)")}${btn('关闭',"easy.menu=false;easyRender()")}</div>`:''}</div>`;easySave()}
function easyContent(){if(easy.step===0&&easy.place===0)return`<div class="easy-dialog"><div class="easy-speaker">织造署管事</div><h3>这批宫中差货，托你承办。</h3><p>请把三包任务送给织工，收齐成品后送到码头。</p>${btn('接下差单 →',"easyNext(1)")}</div>`;if(easy.step===1&&easy.place===1)return`<div class="easy-dialog"><div class="easy-speaker">画师</div><h3>先织个画稿，大家就有统一参照。</h3><p>你也可以直接开工，留到收货时仔细检查。</p><div class="easy-options">${btn('先确认画稿',"easySample(true)")}${btn('直接开工',"easySample(false)")}</div></div>`;if(easy.step===2)return`<div class="easy-packages">${['花卉纹样','枝叶纹样','地纹'].map((n,i)=>`<button class="easy-bundle ${easy.selected===i?'selected':''} ${easy.assigned[i]>=0?'sent':''}"data-easy-bundle="${i}"onclick="easySelect(${i})"aria-label="${n}任务包"><span>▧</span><b>${n}</b><small>${easy.assigned[i]>=0?'已送 '+easyNames[easy.assigned[i]]:easy.selected===i?'再点一家织户':'点选 / 拖给织工'}</small></button>`).join('')}</div>`;if(easy.step===3)return`<div class="easy-dialog compact"><h3>三包任务与丝料，已一并送达。</h3><p>${easy.assigned.map((w,i)=>['花卉','枝叶','地纹'][i]+' → '+easyNames[w]).join('　')}</p>${btn('开始织造 →',"easyNext(4)")}</div>`;if(easy.step===4)return`<div class="easy-dialog"><div class="easy-speaker">织工来信 · 突发事件</div><h3>${easyNames[easy.assigned[0]]}临时有事，进度落后了。</h3><p>${new Set(easy.assigned).size===1?'三包任务都集中在这一户，需要一起协调。':'其他织户仍在承织，只需处理这一户的困难。'}</p><div class="easy-options">${btn('亲自上门帮忙',"easyEvent('help')")}${btn('请另一户协作',"easyEvent('share')")}</div></div>`;if(easy.step===5)return`<div class="easy-counter">行囊中 <b>${easy.collected.length} / 3</b> 包成品</div>`;if(easy.step===6)return`<div class="easy-inspection">${[0,1,2].map((i)=>`<button class="easy-cloth ${easy.checked.includes(i)?'checked':''}"onclick="easyInspect(${i})"aria-label="检查${['花卉','枝叶','地纹'][i]}织面"><span>${['❀','❧','≋'][i]}</span><b>${['花卉','枝叶','地纹'][i]}</b><small>${easy.checked.includes(i)?'✓ 已检查':'点我检查'}</small>${i===1&&!easy.fixed?'<i class="loose-thread">╱</i>':''}</button>`).join('')}</div>${easy.place==='defect'?`<div class="easy-dialog compact"><h3>这里有一处${easy.sample?'松出的线头':'纹样边界偏差'}。</h3><div class="easy-options">${btn('请织工修整',"easyFix(true)")}${btn('带上船再修整',"easyFix(false)")}</div></div>`:''}`;if(easy.step===7&&easy.place===5)return`<div class="easy-dialog compact"><div class="easy-speaker">差船管事</div><h3>成品收齐，可以装船了。</h3><p>${easy.fixed?'织面已经修整妥当。':'船上复查时，再处理已标记的小问题。'}</p>${btn('把三包差货装上船 →',"easyNext(8)")}</div>`;if(easy.step===8)return`<div class="easy-dialog"><div class="easy-speaker">第一关完成</div><h3>差货入京，众手承业。</h3><p>${easy.event==='help'?'你亲自协调，帮助织工完成了承诺。':'你联系其他织户，共同完成了差货。'}${easy.sample?'画稿让大家有了统一参照。':'直接开工后，你在收验中处理了偏差。'}</p><div class="easy-options">${btn('进入第二关 →',"switchCh(1)")}${btn('再试另一种选择',"easyReset()")}</div></div>`;return''}
function easyNext(n){easy.step=n;easy.place=null;easy.notice='';easyRender()}
function easyVisit(i){if(!easyAllowed(i)){easy.notice=i===5&&easy.step<7?'请先完成收验，再到差船装船。':easyGuide[easy.step][1];easyRender();return}if(easy.step===2){if(easy.selected===null){easy.notice='先点下方的一包任务，再点这家织户。';easyRender()}else easyAssign(easy.selected,i-2);return}if(easy.step===5){easyCollect(i-2);return}easy.place=i;easyRender()}
function easySample(yes){easy.sample=yes;easyNext(2);easy.notice=yes?'画稿已确认。现在把三包任务送给织工。':'先直接开工。把三包任务送给织工即可。';easyRender()}
function easySelect(i){if(easy.assigned[i]>=0){easy.notice='这包已经送达。请把剩余任务送给织工。';easyRender();return}easy.selected=i;easy.notice='已拿起'+['花卉','枝叶','地纹'][i]+'任务包。现在点一家发光的织户。';easyRender()}
