function easyEvent(type){easy.event=type;if(type==='share'){let old=easy.assigned[0],next=(old+1)%3;easy.assigned[0]=next}easyNext(5);easy.notice=type==='help'?'你上门协调，织工完成了任务。点击「收货」。':'另一户接手协作，成品已经下机。点击「收货」。';easyRender()}
function easyCollect(w){easy.assigned.forEach((a,i)=>{if(a===w&&!easy.collected.includes(i))easy.collected.push(i)});if(easy.collected.length===3)easyNext(6);else{easy.notice='已收回成品，再去收剩下的。';easyRender()}}
function easyInspect(i){if(easy.step!==6)return;if(i===1&&!easy.fixed&&!easy.checked.includes(1)){easy.place='defect';easyRender();return}if(!easy.checked.includes(i))easy.checked.push(i);easy.place=null;if(easy.checked.length===3)easyNext(7);else{easy.notice='这块织面已检查，继续点其余织面。';easyRender()}}
